/**
 * Nova Tools Forge brand images, all from one source: emblem.png (1254×1254, generated by the
 * owner with ChatGPT, 2026-10-30).
 *
 *   npm i --no-save sharp      (once, in this folder)
 *   node render.mjs
 *
 * Writes, each checked against the place it is uploaded to:
 *   avatar-1024.png        GitHub organisation picture           ≤ 1 MB
 *   play-icon-512.png      Play developer page icon, 512×512      24-bit PNG, no alpha, ≤ 1 MB
 *   play-header.jpg        Play developer page header, 4096×2304  JPEG, ≤ 1 MB
 */

import sharp from 'sharp';
import { statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = join(HERE, 'emblem.png');
/** The emblem's own background, sampled from its border (#0f0922 … #140e29). */
const GROUND = { r: 0x11, g: 0x0b, b: 0x25 };
const MB = 1024 * 1024;

async function check(file, { width, height, maxBytes, alpha = false }) {
  const meta = await sharp(file).metadata();
  const bytes = statSync(file).size;
  const problems = [];
  if (meta.width !== width || meta.height !== height) problems.push(`${meta.width}×${meta.height}`);
  if (!alpha && meta.hasAlpha) problems.push('has an alpha channel');
  if (bytes > maxBytes) problems.push(`${(bytes / MB).toFixed(2)} MB`);
  if (problems.length) throw new Error(`${file}: ${problems.join(', ')}`);
  console.log(`${file.replace(HERE, '.')}  ${width}×${height}  ${(bytes / 1024).toFixed(0)} KB`);
}

// Avatar: the emblem as it is, a little smaller.
const avatar = join(HERE, 'avatar-1024.png');
await sharp(SRC).resize(1024, 1024).removeAlpha().png({ compressionLevel: 9, palette: false }).toFile(avatar);
await check(avatar, { width: 1024, height: 1024, maxBytes: MB });

// Play icon: 512, opaque 24-bit.
const icon = join(HERE, 'play-icon-512.png');
await sharp(SRC).resize(512, 512).removeAlpha().png({ compressionLevel: 9 }).toFile(icon);
await check(icon, { width: 512, height: 512, maxBytes: MB });

// Play header: the emblem centred on its own ground, edges feathered so no seam shows.
const W = 4096;
const H = 2304;
const size = 1600;
const feather = 160;
const black = { r: 0, g: 0, b: 0 };
const white = { r: 255, g: 255, b: 255 };
const inner = await sharp({ create: { width: size - 2 * feather, height: size - 2 * feather, channels: 3, background: white } })
  .png()
  .toBuffer();
const mask = await sharp(
  await sharp({ create: { width: size, height: size, channels: 3, background: black } })
    .composite([{ input: inner, left: feather, top: feather }])
    .png()
    .toBuffer(),
)
  .blur(feather / 2)
  .extractChannel(0)
  .raw()
  .toBuffer();
const emblem = await sharp(SRC)
  .resize(size, size)
  .removeAlpha()
  .joinChannel(mask, { raw: { width: size, height: size, channels: 1 } })
  .png()
  .toBuffer();
const header = join(HERE, 'play-header.jpg');
await sharp({ create: { width: W, height: H, channels: 3, background: GROUND } })
  .composite([{ input: emblem, left: (W - size) / 2, top: (H - size) / 2 }])
  .jpeg({ quality: 88, chromaSubsampling: '4:4:4', mozjpeg: true })
  .toFile(header);
await check(header, { width: W, height: H, maxBytes: MB });
